import java.util.Scanner;

public class cf2 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        scanner.nextLine();
        int totalPairsCount = 0;
        int maxRun = 0;
        String inputLine = scanner.nextLine();

        for (int index = 0; index < totalChars; index++) {
            int currentRun = 0;
            int parenthesesPairs = 0;
            for (int position = 0; position < totalChars; position++) {
                char c = inputLine.charAt(position);
                if (c == '_') {
                    continue;
                } else if (c == '(') {
                    position++;
                    while (position < totalChars && inputLine.charAt(position) != ')') {
                        if (inputLine.charAt(position) != '_' && inputLine.charAt(position) != ')') {
                            parenthesesPairs++;
                            while (position < totalChars && inputLine.charAt(position) != '_' && inputLine.charAt(position) != ')') {
                                position++;
                            }
                        }
                        position++;
                    }
                } else {
                    if (c != '_' && c != '(' && c != ')') {
                        currentRun = 0;
                        while (position < totalChars && inputLine.charAt(position) != '_' && inputLine.charAt(position) != '(' && inputLine.charAt(position) != ')') {
                            currentRun++;
                            position++;
                        }
                        if (currentRun > maxRun) {
                            maxRun = currentRun;
                        }
                        position--;
                    }
                }
            }
            totalPairsCount += parenthesesPairs;
        }
        System.out.println(maxRun + " " + totalPairsCount);
